using System;using System.IO;using System.Linq;using System.Reflection;using System.Drawing;using System.Drawing.Imaging;using System.Windows.Forms;using JouchoPet;
class UtilityCheck {
 const string Folder="qa/v0734/";const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;static int checks;
 static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static object Field(object o,string name){return o.GetType().GetField(name,F).GetValue(o);}static void Set(object o,string name,object v){o.GetType().GetField(name,F).SetValue(o,v);}static object Call(object o,string name,params object[] v){return o.GetType().GetMethod(name,F).Invoke(o,v);}
 [STAThread]static void Main(string[] args){try{AnimationParameters.UseFixedValues();Directory.CreateDirectory(Folder);if(args.Length>0&&args[0]=="live"){Live();return;}if(args.Length>0&&args[0]=="preview"){Preview();return;}Geometry();Timelines();Integration();Regression();Console.WriteLine("All "+checks+" checks passed.");}catch(Exception e){Console.WriteLine(e);Environment.ExitCode=1;}}
 static void Geometry(){foreach(int size in new[]{220,300,400})using(var r=new PetRenderer()){r.Resize(size);foreach(int dir in new[]{-1,1})foreach(int dy in new[]{-100,0,100}){var target=new PointF(r.Reach.Padding+dir*size*2,120+dy);var rest=r.Reach.Sample(dir,0,target);bool lengths=true,continuous=true;var previous=rest;for(int k=0;k<=200;k++){var n=r.Reach.Sample(dir,k/200.0,target);lengths&=Math.Abs(RigParts.Length(n.Shoulder,n.Elbow)-RigParts.Length(rest.Shoulder,rest.Elbow))<.001&&Math.Abs(RigParts.Length(n.Elbow,n.Wrist)-RigParts.Length(rest.Elbow,rest.Wrist))<.001;continuous&=RigParts.Length(previous.Tip,n.Tip)<size*.015;previous=n;}Check(lengths&&continuous,"single arm lengths / continuity "+size+" / "+dir+" / "+dy);}
  var c=PetRenderer.CanvasSize(size);using(var art=CharacterArt.Normalized("front",c.Width,c.Height,size))using(var arm=new GreetingArmRig(PoseMesh.Read(art),c.Width,c.Height,size)){var rest=arm.HairSample(0,0,p=>p,0);foreach(bool scout in new[]{false}){bool valid=true;var previous=rest;for(int k=0;k<=200;k++){var n=arm.HairSample(k/200.0,.5,p=>p,0);valid&=Math.Abs(Math.Sqrt(Math.Pow(RigParts.Length(n.Shoulder,n.Elbow),2)+n.UpperDepth*n.UpperDepth)-RigParts.Length(rest.Shoulder,rest.Elbow))<.001&&Math.Abs(RigParts.Length(n.Elbow,n.Wrist)-RigParts.Length(rest.Elbow,rest.Wrist))<.001&&RigParts.Length(previous.Tip,n.Tip)<size*.02;previous=n;}Check(valid,"front arm fixed bones / continuous "+scout+" / "+size);}}
 }}
 static void Timelines(){using(var b=new Bitmap(300,300))using(var g=Graphics.FromImage(b)){foreach(double age in new[]{.05,.30,.58,.70}){g.Clear(Color.Transparent);UtilityArt.BeamImpact(g,new PointF(150,150),age,300);Check(PoseMesh.Read(b).Count(p=>((uint)p>>24)>30)>20,"welding sparks visible throughout contact and decay / "+age);}g.Clear(Color.Transparent);UtilityArt.BeamImpact(g,new PointF(150,150),.96,300);Check(PoseMesh.Read(b).All(p=>p==0),"impact fully disappears");}Check(DailyMotion.At(DailyAction.Hair,.90).Stroke==0&&DailyMotion.At(DailyAction.Hair,.9625).Stroke>.49&&DailyMotion.At(DailyAction.Hair,1.15).Stroke<.001&&DailyMotion.At(DailyAction.Hair,1.4).Stroke<.001,"scratch repeats and returns at contact");Check(UtilityMotion.Reach(UtilityAction.Beam,1.09)==1&&Math.Abs(UtilityMotion.Reach(UtilityAction.Beam,1.65))<1e-9,"arm holds until extended beam ends");Check(Math.Abs(UtilityArt.BeamWidth(300)-3.6)<.001,"beam width is exactly three times previous");var ends=UtilityArt.TetherEnds(new PointF(101.5f,205.5f),40);Check(ends.Length==3&&ends[0].Y<ends[1].Y&&ends[1].Y<ends[2].Y&&ends[1]==new PointF(101.5f,205.5f),"three tethers use icon top / exact center / bottom");using(var source=new Bitmap(100,100))using(var output=new Bitmap(100,100))using(var g=Graphics.FromImage(output)){for(int k=0;k<=135;k++)UtilityArt.Teleport(g,source,k*.01,80);Check(true,"teleport particles valid through transparent interval and recovery");}Check(UtilityMotion.Opacity(0)==1&&UtilityMotion.Opacity(.55)==0&&UtilityMotion.Opacity(.65)==0&&UtilityMotion.Opacity(.70)==0&&UtilityMotion.Opacity(1.3)==1,"teleport relocation fully invisible, appearance restored");Check(UtilityMotion.BeamAlpha(.49)==0&&UtilityMotion.BeamAlpha(.8)>.99&&UtilityMotion.BeamAlpha(1.09)>0&&UtilityMotion.BeamAlpha(1.10)==0,"beam lasts 0.60 s (three times)");
  foreach(double transit in new[]{1.05,3.5}){PointF a=new PointF(-640,370),b=new PointF(340,430);bool smooth=true;var prev=a;for(int k=0;k<=800;k++){var p=UtilityMotion.IconAt(a,b,k*.01,30,transit);smooth&=RigParts.Length(p,prev)<20;prev=p;}Check(smooth&&UtilityMotion.IconAt(a,b,0,30,transit)==a&&UtilityMotion.IconAt(a,b,8,30,transit)==b,"icon continuous lift / traverse / exact landing with negative monitor origin "+transit);Check(UtilityMotion.IconAt(a,b,1.05,30,transit).Y==340,"icon lifts before translating");}
  foreach(double at in new[]{.1,.5,1.1,2.4}){var d=new DailyMotion();d.Request(DailyAction.Lookout);d.Update(.01,true);d.Update(at,true);var p=d.Pose;d.Cancel();Check(d.Pose.Scout==p.Scout,"lookout cancellation starts from current pose");d.Update(.25,true);Check(!d.Busy&&d.Pose.Scout==0,"lookout cancellation restores face and arm");}
 }
 static void Integration(){using(var pet=new Pet()){Set(pet,"settings",Path.GetFullPath(Folder+"test-settings.txt"));Set(pet,"wandering",false);var motion=(Motion)Field(pet,"motion");var u=(UtilityMotion)Field(pet,"utility");var daily=(DailyMotion)Field(pet,"daily");Rectangle area=Screen.PrimaryScreen.WorkingArea;pet.Location=new Point(area.Left+Math.Min(100,area.Width/4),area.Top+100);
  Point target=new Point(area.Right-100,area.Top+200);foreach(int dir in new[]{-1,1}){motion.FollowPush(0,0,dir,300);Check(pet.LightBeam(target),"beam request from direction "+dir);bool began=false;for(int i=0;i<400;i++){Call(pet,"UpdateUtility",1.0/60);if(!u.Active)motion.Update(1.0/60,(int)Call(pet,"UtilityDesired"),300,u.Busy);began|=u.Active;}Check(began&&!u.Busy,"beam enters after turn and finishes / "+dir);}
  var menu=(ContextMenuStrip)Field(pet,"menu");int lookouts=0;foreach(ToolStripItem group in menu.Items){var parent=group as ToolStripMenuItem;if(parent!=null)foreach(ToolStripItem item in parent.DropDownItems)if(item.Text.Contains("张望"))lookouts++;}Check(lookouts==1,"one lookout entry in Daily menu");
  var center=DesktopFileTarget.Center(new Rectangle(101,203,33,35));Check(center==new PointF(117.5f,220.5f),"file center preserves half pixels");
  motion.FollowPush(0,0,1,300);pet.LightBeam(target);bool present=true;Set(pet,"beamFile",new DesktopFileTarget("test-only",center,id=>present?(PointF?)center:null));Set(pet,"utilityTarget",center);Call(pet,"UpdateUtility",.01);Call(pet,"UpdateUtility",.49);Check(u.Active&&(PointF)Field(pet,"utilityTarget")==center,"locked beam retains exact file center");present=false;Call(pet,"UpdateUtility",.02);Check(!u.Busy&&Field(pet,"beamFile")==null,"missing file cancels before hit and releases lease");
  motion.Reset();Point dest=new Point(area.Left+area.Width/2,area.Bottom-20);Point old=pet.Location;Check(pet.Teleport(dest),"teleport accepted");Call(pet,"UpdateUtility",.01);Call(pet,"UpdateUtility",.64);Check(pet.Location==old,"no relocation before transparent frame");Call(pet,"UpdateUtility",.02);Point moved=pet.Location;Check(moved!=old&&u.Relocated,"teleport relocation occurs once while invisible");pet.CancelUtilityAction();Check(!u.Busy&&pet.Location==moved,"cancel after relocation keeps destination and restores normal render");
  motion.Reset();pet.LightBeam(target);Call(pet,"UpdateUtility",.01);Set(pet,"dragging",true);Call(pet,"UpdateUtility",.01);Check(!u.Busy&&!pet.Teleport(dest),"drag cancels and rejects utility actions");Set(pet,"dragging",false);
  motion.Reset();Check(pet.LookOut(),"semantic lookout entry");Call(pet,"UpdateDaily",.01);Check(!daily.Active&&daily.Pending,"lookout waits for body turn");for(int i=0;i<120&&!daily.Active;i++){motion.Update(1.0/60,(int)Call(pet,"DailyDesired"),300,true);Call(pet,"UpdateDaily",1.0/60);}Check(daily.Active&&motion.Facing!=0&&!pet.LightBeam(target),"lookout turns before posing; daily and utility exclusive");pet.CancelDailyAction();Call(pet,"UpdateDaily",.25);Check(!daily.Busy,"lookout neutral after cancellation");
  motion.Reset();pet.LightBeam(target);Set(pet,"menuOpen",true);Call(pet,"UpdateUtility",.3);Check(u.Age==0&&u.Pending,"menu pauses utility timeline");Set(pet,"menuOpen",false);pet.CancelUtilityAction();
 }}
 static object ConvertValue(object v,Type t){if(v==null||t.IsPrimitive||t==typeof(string))return v;object o=Activator.CreateInstance(t);foreach(var f in t.GetFields(F)){var s=v.GetType().GetField(f.Name,F);if(s!=null)f.SetValue(o,ConvertValue(s.GetValue(v),f.FieldType));}return o;}
 static void Regression(){var old=Assembly.LoadFile(Path.GetFullPath(Folder+"baseline/IsekaijouchoPet.exe"));var type=old.GetType("JouchoPet.PetRenderer");object before=Activator.CreateInstance(type,true);using(var now=new PetRenderer()){now.Resize(300);Call(before,"Resize",300);try{
  foreach(var frame in new[]{new RenderFrame{MotionState="idle"},new RenderFrame{MotionState="idle",RestAmount=1},new RenderFrame{MotionState="idle",Greeting=1,WaveBlend=1},new RenderFrame{MotionState="walk",Facing=-1,Speed=-198,Gait=.7,RunBlend=1},new RenderFrame{MotionState="walk",Facing=1,Speed=198,Gait=.7,RunBlend=1},new RenderFrame{MotionState="hold",Facing=-1,Carry=1},new RenderFrame{MotionState="hold",Facing=1,Carry=1},new RenderFrame{Archery=true,BowPose=ArcheryMotion.At(2,-1)},new RenderFrame{Archery=true,BowPose=ArcheryMotion.At(2,1)},new RenderFrame{MotionState="idle",Daily=DailyMotion.At(DailyAction.Wink,.6)},new RenderFrame{MotionState="idle",Daily=DailyMotion.At(DailyAction.Thinking,.7)}}){var pixels=PoseMesh.Read((Bitmap)Call(before,"Draw",ConvertValue(frame,old.GetType("JouchoPet.RenderFrame"))));Check(pixels.SequenceEqual(PoseMesh.Read(now.Draw(frame))),"v0.7.33 pixels unchanged: "+frame.MotionState+" / "+frame.Facing+" / "+frame.Archery);}
  foreach(int dir in new[]{-1,1}){var sword=SwordMotion.At(.6,dir);Check(PoseMesh.Read((Bitmap)Call(before,"DrawSword",ConvertValue(sword,old.GetType("JouchoPet.SwordPose")),true)).SequenceEqual(PoseMesh.Read(now.DrawSword(sword,true))),"sword frozen / "+dir);var cast=CastingMotion.At(1.9,dir,25);Check(PoseMesh.Read((Bitmap)Call(before,"DrawCast",ConvertValue(cast,old.GetType("JouchoPet.CastPose")),true)).SequenceEqual(PoseMesh.Read(now.DrawCast(cast,true))),"casting frozen / "+dir);}
 }finally{((IDisposable)before).Dispose();}}}
 // Render native frames, not browser approximations. Only the icon below is a fixture.
 static Bitmap Scene(PetRenderer r,string kind,double t,int size,int dir=1){var c=PetRenderer.CanvasSize(size);int w=(int)(size*2.1),h=c.Height;var b=new Bitmap(w,h);using(var g=Graphics.FromImage(b)){g.Clear(Color.FromArgb(42,47,57));int x=dir<0?w-c.Width:0;PointF local=new PointF(dir>0?w*.80f:-w*.52f,(float)(size*.38));
   if(kind=="beam"||kind=="lift"){double q=UtilityMotion.Reach(kind=="beam"?UtilityAction.Beam:UtilityAction.Levitate,t);g.DrawImageUnscaled(r.Reach.Draw(dir,q,local),x-r.Reach.Padding,-r.Reach.Padding);var hand=RigParts.Add(r.Reach.Sample(dir,q,local).Tip,x,0);if(kind=="beam"){var center=RigParts.Add(local,x,0);using(var brush=new SolidBrush(Color.FromArgb(180,220,234,248)))g.FillRectangle(brush,center.X-12,center.Y-16,24,32);g.DrawString("FILE",SystemFonts.DefaultFont,Brushes.SlateGray,center.X-12,center.Y-4);UtilityArt.Beam(g,hand,RigParts.Add(local,x,0),UtilityMotion.BeamAlpha(t),size,t);UtilityArt.BeamImpact(g,RigParts.Add(local,x,0),t-.5,size);}else{var p=UtilityMotion.IconAt(new PointF(w*.60f,size*.65f),new PointF(w*.86f,size*.65f),t,size*.10);using(var brush=new SolidBrush(Color.FromArgb(220,220,239,255)))g.FillRectangle(brush,p.X-13,p.Y-17,26,34);g.DrawString("TEST",SystemFonts.DefaultFont,Brushes.LightSlateGray,p.X-13,p.Y-4);UtilityArt.Tethers(g,hand,p,34,t<.45?0:q,size,t);}}
   else if(kind=="lookout"){if(t<.64||t>=3.54){double angle=t<.64?dir*DailyMotion.Ease(t/.64):dir*(1-DailyMotion.Ease((t-3.54)/.64));g.DrawImageUnscaled(r.Draw(new RenderFrame{MotionState="turn",Angle=angle,Time=t}),x,0);}else g.DrawImageUnscaled(r.Reach.DrawLookout(dir,DailyMotion.At(DailyAction.Lookout,t-.64,1.8).Scout),x-r.Reach.Padding,-r.Reach.Padding);}
   else if(kind=="teleport"){var image=r.Draw(new RenderFrame{MotionState="idle",Time=t});g.TranslateTransform(t<.65?0:w-c.Width,0);UtilityArt.Teleport(g,image,t,size);}
   else{var d=DailyMotion.At(kind=="hair"?DailyAction.Hair:DailyAction.Lookout,t);g.DrawImageUnscaled(r.Draw(new RenderFrame{MotionState="idle",Time=t,Daily=d,LookX=kind=="lookout"?.12*Math.Sin(t):0,LookY=kind=="lookout"?-.12:0}),x,0);}
  }return b;}
 static void Preview(){foreach(int size in new[]{220,300,400})using(var r=new PetRenderer()){r.Resize(size);foreach(string kind in new[]{"hair","lookout","beam","lift","teleport"}){double duration=kind=="hair"?2.05:kind=="lookout"?4.18:kind=="beam"?1.65:kind=="lift"?3.25:1.3;double[] times=kind=="hair"?new[]{0,.55,.9625,1.2125,1.9}:kind=="lookout"?new[]{0,.32,1.3,2.8,3.9}:kind=="beam"?new[]{0,.3,.8,1.05,1.64}:kind=="lift"?new[]{0,.8,1.5,2.45,3.1}:new[]{0,.3,.6,.9,1.3};int w=(int)(size*2.1),h=PetRenderer.CanvasSize(size).Height;
   using(var sheet=new Bitmap(w*5,h+25))using(var g=Graphics.FromImage(sheet)){g.Clear(Color.FromArgb(42,47,57));for(int i=0;i<5;i++)using(var frame=Scene(r,kind,times[i],size)){g.DrawImageUnscaled(frame,i*w,25);g.DrawString(kind+" "+times[i].ToString("F2")+"s",SystemFonts.DefaultFont,Brushes.White,i*w+8,4);}sheet.Save(Folder+kind+"-"+size+".png");}
   if(kind=="hair")using(var detail=Scene(r,kind,.9625,size))detail.Save(Folder+"scratch-"+size+".png");if(size==300){int n=(int)Math.Ceiling(duration*24)+1;using(var atlas=new Bitmap(w*6,h*((n+5)/6)))using(var g=Graphics.FromImage(atlas)){for(int i=0;i<n;i++)using(var frame=Scene(r,kind,i/24.0,size))g.DrawImageUnscaled(frame,i%6*w,i/6*h);atlas.Save(Folder+kind+"-atlas.png");}}
  }
  foreach(int dir in new[]{-1,1}){using(var b=Scene(r,"beam",.8,size,dir))b.Save(Folder+"beam-"+dir+"-"+size+".png");using(var b=Scene(r,"lookout",1.3,size,dir))b.Save(Folder+"lookout-"+dir+"-"+size+".png");var rest=r.Reach.SampleLookout(dir,0);bool valid=true;var prev=rest;for(int k=0;k<=200;k++){var n=r.Reach.SampleLookout(dir,k/200.0);valid&=Math.Abs(RigParts.Length(rest.Shoulder,rest.Elbow)-Math.Sqrt(Math.Pow(RigParts.Length(n.Shoulder,n.Elbow),2)+n.UpperDepth*n.UpperDepth))<.001&&Math.Abs(RigParts.Length(rest.Elbow,rest.Wrist)-RigParts.Length(n.Elbow,n.Wrist))<.001&&RigParts.Length(prev.Tip,n.Tip)<size*.02;prev=n;}Check(valid,"lookout side bones and continuity / "+size+" / "+dir);var held=r.Reach.SampleLookout(dir,1);Check(Math.Abs(RigParts.Length(held.Shoulder,held.Elbow)/RigParts.Length(rest.Shoulder,rest.Elbow)-.82)<.001,"lookout upper arm foreshortened 18 percent / "+size+" / "+dir);double dot=(held.Shoulder.X-held.Elbow.X)*(held.Wrist.X-held.Elbow.X)+(held.Shoulder.Y-held.Elbow.Y)*(held.Wrist.Y-held.Elbow.Y);double angle=Math.Acos(dot/(RigParts.Length(held.Shoulder,held.Elbow)*RigParts.Length(held.Elbow,held.Wrist)))*180/Math.PI;Check(Math.Abs(angle-150)<.01,"lookout interior elbow 150 degrees / "+size+" / "+dir);Check(held.Elbow.Y<held.Shoulder.Y&&Math.Abs(held.Elbow.Y-held.Shoulder.Y)>Math.Abs(held.Elbow.X-held.Shoulder.X)&&Math.Abs(held.Wrist.X-held.Elbow.X)>Math.Abs(held.Wrist.Y-held.Elbow.Y),"lookout upper arm up / forearm horizontal / "+size+" / "+dir);}
 }}
 static void Live(){Application.EnableVisualStyles();using(var pet=new Pet())using(var host=new Form{Text="轻魔法动作验收 v0.7.34",Width=1050,Height=700,StartPosition=FormStartPosition.CenterScreen,BackColor=Color.FromArgb(42,47,57)}){
  Set(pet,"settings",Path.GetFullPath(Folder+"live-settings.txt"));Set(pet,"wandering",false);Set(pet,"petHeight",300);Call(pet,"ResizePet");var handle=pet.Handle;var r=(PetRenderer)Field(pet,"renderer");var motion=(Motion)Field(pet,"motion");var u=(UtilityMotion)Field(pet,"utility");var d=(DailyMotion)Field(pet,"daily");pet.Location=new Point(80,100);
  var controls=new FlowLayoutPanel{Dock=DockStyle.Top,Height=45};var picture=new PictureBox{Left=10,Top=55,Width=630,Height=400};var info=new Label{Left=10,Top=465,Width=1000,ForeColor=Color.White};var strip=new PictureBox{Left=10,Top=500,Width=1000,Height=150,SizeMode=PictureBoxSizeMode.Zoom};host.Controls.Add(controls);host.Controls.Add(picture);host.Controls.Add(info);host.Controls.Add(strip);string action="",previous="";int captured=0;Bitmap sheet=null;
  Action<string,Action> button=(name,fn)=>{var b=new Button{Text=name,AutoSize=true};b.Click+=delegate{fn();};controls.Controls.Add(b);};Action reset=()=>{pet.CancelUtilityAction();d.Reset();motion.Reset();Set(pet,"sleeping",false);Set(pet,"rest",new RestMotion());Set(pet,"lastInput",DateTime.UtcNow);};
  button("Scratch",()=>{reset();pet.ScratchHead();action="hair";});button("Lookout",()=>{reset();pet.LookOut();action="lookout";});button("Beam R",()=>{reset();pet.LightBeam(new Point(pet.Left+500,pet.Top+114));action="beam";});button("Beam L",()=>{reset();pet.Location=new Point(650,100);pet.LightBeam(new Point(100,214));action="beam";});button("Teleport",()=>{reset();pet.Teleport(new Point(pet.Left<400?800:200,650));action="teleport";});button("Cancel",()=>{pet.CancelUtilityAction();pet.CancelDailyAction();});button("Menu",()=>((ContextMenuStrip)Field(pet,"menu")).Show(host,new Point(10,45)));
  using(var timer=new Timer{Interval=16}){timer.Tick+=delegate{Call(pet,"Animate",null,EventArgs.Empty);bool active=u.Active||d.Active;double age=u.Active?u.Age:d.Age;Bitmap image;
   if(active)image=Scene(r,action,action=="lookout"?age+.64:age,300,u.Active?u.Facing:action=="lookout"?(int)Field(pet,"lookoutFacing"):1);else{image=new Bitmap(630,348);using(var g=Graphics.FromImage(image)){g.Clear(host.BackColor);g.DrawImageUnscaled(r.Draw(new RenderFrame{MotionState=motion.State,Facing=motion.Facing,Angle=motion.Angle,Settle=motion.Settle,Time=(double)Field(pet,"elapsed")}),0,0);}}
   var old=picture.Image;picture.Image=image;if(old!=null)old.Dispose();info.Text=active?action+" / "+age.ToString("F2")+" s":"Idle · Pet.Animate 实际执行，图标实移动需用户在菜单选定";
   if(active&&previous!=action){previous=action;captured=0;if(sheet!=null)sheet.Dispose();sheet=new Bitmap(630*4,348);using(var g=Graphics.FromImage(sheet))g.Clear(host.BackColor);}
   double[] marks=action=="teleport"?new[]{0,.30,.6,.95}:action=="beam"?new[]{0,.3,.8,1.3}:action=="hair"?new[]{0,.55,1.2125,1.85}:new[]{0,.3,1.0,2.5};
   if(active&&captured<4&&age>=marks[captured]){using(var g=Graphics.FromImage(sheet))g.DrawImageUnscaled(image,captured*630,0);captured++;sheet.Save(Folder+"live-"+action+".png");var prior=strip.Image;strip.Image=(Bitmap)sheet.Clone();if(prior!=null)prior.Dispose();}if(!active)previous="";
  };host.Shown+=delegate{timer.Start();};host.FormClosed+=delegate{timer.Stop();};Application.Run(host);}pet.CancelUtilityAction();if(picture.Image!=null)picture.Image.Dispose();if(strip.Image!=null)strip.Image.Dispose();if(sheet!=null)sheet.Dispose();
 }}
